{"implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    total_min = sum(s['minimum'] for s in segments)
    total_cap = sum(s['capacity'] for s in segments)
    if budget < total_min or budget > total_cap:
        return {"error": "budget out of bounds", "allocations": {}, "name_mapping": [s['name'] for s in segments], "total": 0}
    names = [s['name'] for s in segments]
    cur_alloc = [s['minimum'] for s in segments]
    caps = [s['capacity'] for s in segments]
    importances = [s['importance'] for s in segments]
    remaining = budget - total_min
    n = len(segments)
    while remaining > 0:
        best_idx = -1
        best_ratio = -1.0
        for i in range(n):
            if cur_alloc[i] < caps[i]:
                ratio = importances[i] / (cur_alloc[i] + 1.0)
                if ratio > best_ratio:
                    best_ratio = ratio
                    best_idx = i
        if best_idx == -1:
            break
        cur_alloc[best_idx] += 1
        remaining -= 1
    alloc = {names[i]: cur_alloc[i] for i in range(n)}
    total = sum(cur_alloc)
    return {"allocations": alloc, "name_mapping": names, "total": total}"}
